var e=[{id:1,title:`Trekking & Painting`,slug:`trekking-painting`,tagline:`Paint the Himalayas while trekking through nature`,description:`Experience the ultimate artistic adventure by combining the thrill of trekking through the majestic Himalayas with the tranquility of plein air painting. Guided by professional artists and experienced mountain guides, you will capture the breathtaking landscapes, vibrant local culture, and pristine nature of Nepal on your canvas. Suitable for all skill levels, from beginners to advanced painters.`,features:[`Professional artist guide`,`All art supplies included`,`Experienced trekking guide`,`Accommodation & meals`,`Porter service`,`Small group size`],pricing:`Starting from $300 per person`,duration:`3-7 days`,image:`/photos/paintings-of-nepal-1.jpg`,gallery:[`/photos/paintings-of-nepal-2.jpg`,`/photos/paintings-of-nepal-3.jpg`,`/photos/paintings-of-nepal-4.jpg`],category:`experience`},{id:3,title:`Wedding Live Painting`,slug:`wedding-live-painting`,tagline:`Capture your special day on canvas`,description:`Preserve the magic of your wedding day with a live, custom-painted masterpiece. Our artist will attend your wedding and paint a significant moment—such as the ceremony, first dance, or reception—as it unfolds. This not only provides a unique entertainment element for your guests but also leaves you with a timeless heirloom to cherish forever.`,features:[`Pre-wedding consultation`,`Live painting during the event`,`Premium canvas and oils/acrylics`,`Touch-ups in studio`,`Framing options`,`Travel within Pokhara, Kathmandu, and nationwide`],pricing:`Starting from $500`,duration:`4-8 hours`,image:`/photos/photo-wedding.png`,gallery:[`/photos/photo-wedding.png`,`/photos/paintings-of-nepal-6.jpg`,`/photos/paintings-of-nepal-7.jpg`,`/photos/paintings-of-nepal-8.jpg`],category:`event`},{id:2,title:`Live Painting`,slug:`live-painting`,tagline:`Bring your events to life with live art creation`,description:`Transform your special event into an unforgettable experience with our live painting service. Watch as a blank canvas evolves into a stunning masterpiece right before your eyes, capturing the energy, emotion, and atmosphere of your gathering. Perfect for corporate events, galas, festivals, and grand openings.`,features:[`Professional live artist`,`Customized theme`,`High-quality materials`,`Finished artwork delivered`,`Interactive experience`,`Setup and cleanup included`],pricing:`Starting from $400 per event`,duration:`2-6 hours`,image:`/photos/paintings-of-nepal-9.jpg`,gallery:[`/photos/paintings-of-nepal-10.jpg`,`/photos/paintings-of-nepal-11.jpg`,`/photos/paintings-of-nepal-12.jpg`],category:`service`},{id:4,title:`Custom Portraits`,slug:`custom-portraits`,tagline:`Timeless portraits created from your photos or from life`,description:`Commission a beautiful, hand-painted portrait of yourself, a loved one, or a respected mentor. We work closely with you to understand the personality and essence of the subject, ensuring the final piece is not just a likeness, but a true reflection of their spirit.`,features:[`Choice of medium (oil, watercolor, charcoal)`,`Various size options`,`Progress updates`,`High level of detail`,`Satisfaction guarantee`,`Professional packaging`],pricing:`Starting from $150`,duration:`2-4 weeks`,image:`/photos/paintings-of-nepal-13.jpg`,gallery:[`/photos/paintings-of-nepal-14.jpg`,`/photos/paintings-of-nepal-15.jpg`,`/photos/paintings-of-nepal-16.jpg`],category:`commission`},{id:5,title:`Family Paintings`,slug:`family-paintings`,tagline:`Celebrate your family bond with custom artwork`,description:`A custom family painting is a beautiful way to celebrate your shared history and love. Whether it is a classical group portrait or a more contemporary, abstract representation of your family dynamics, our artists will create a meaningful piece that will be passed down through generations.`,features:[`Multiple subjects`,`Custom background`,`Choice of style`,`Premium archival materials`,`Consultation on composition`,`Certificate of authenticity`],pricing:`Starting from $300`,duration:`3-6 weeks`,image:`/photos/paintings-of-nepal-17.jpg`,gallery:[`/photos/paintings-of-nepal-18.jpg`,`/photos/paintings-of-nepal-1.jpg`,`/photos/paintings-of-nepal-2.jpg`],category:`commission`},{id:6,title:`Landscape Commissions`,slug:`landscape-commissions`,tagline:`Bring your favorite places into your home`,description:`Do you have a special place that holds fond memories? A childhood home, a breathtaking view from a memorable vacation, or a serene local park? Commission a custom landscape painting to bring that beloved scenery into your everyday living space.`,features:[`Painted from your photos`,`Custom sizing`,`Atmospheric and moody styles`,`High-quality canvas`,`Regular progress updates`,`Free local delivery`],pricing:`Starting from $200`,duration:`2-5 weeks`,image:`/photos/paintings-of-nepal-3.jpg`,gallery:[`/photos/paintings-of-nepal-4.jpg`,`/photos/paintings-of-nepal-5.jpg`,`/photos/paintings-of-nepal-6.jpg`],category:`commission`},{id:7,title:`Pet Paintings`,slug:`pet-paintings`,tagline:`Honor your furry friends with a vibrant portrait`,description:`Our pets are cherished members of the family. Celebrate their unique personality and unconditional love with a custom hand-painted portrait. We capture the sparkle in their eyes and the texture of their fur, creating a lively and heartwarming tribute.`,features:[`All types of pets welcome`,`Expressive styles`,`Focus on eyes and character`,`Various size options`,`Perfect for gifts`,`Fast turnaround available`],pricing:`Starting from $100`,duration:`1-3 weeks`,image:`/photos/paintings-of-nepal-7.jpg`,gallery:[`/photos/paintings-of-nepal-8.jpg`,`/photos/paintings-of-nepal-9.jpg`,`/photos/paintings-of-nepal-10.jpg`],category:`commission`},{id:8,title:`Corporate Gifts`,slug:`corporate-gifts`,tagline:`Unique and memorable art pieces for clients and employees`,description:`Stand out from the crowd with custom artwork for your corporate gifting needs. Whether recognizing a retiring executive, celebrating a company milestone, or thanking key clients, an original painting or a limited edition print offers a sophisticated and lasting impression.`,features:[`Bulk order discounts`,`Branding options`,`Customized themes`,`High-quality prints or originals`,`Elegant packaging`,`Direct shipping to recipients`],pricing:`Custom quote based on volume`,duration:`Varies`,image:`/photos/paintings-of-nepal-11.jpg`,gallery:[`/photos/paintings-of-nepal-12.jpg`,`/photos/paintings-of-nepal-13.jpg`,`/photos/paintings-of-nepal-14.jpg`],category:`service`}];export{e as t};